+static void ghost_sysfs_unregister(struct swap_info_struct *si)
+{
+	if (!si->ghost_kobj)
+		return;
+	sysfs_remove_groups(si->ghost_kobj, ghost_groups);
+	kobject_put(si->ghost_kobj);
+	si->ghost_kobj = NULL;
