 err_destroy_pool:
 	gen_pool_destroy(genpool);
 
@@ -2139,6 +2269,8 @@ static void stratix10_svc_drv_remove(struct platform_device *pdev)
 	if (ctrl->genpool)
 		gen_pool_destroy(ctrl->genpool);
